{
  "query": "query Cart { cart { ... on CartData { order { id name amountTotal partner { id name email } orderLines { id name quantity product { id name defaultCode } } brochureLines { id brochureId brochureName machineSerial partNumber commentary } } } } }",
  "variables": {}
}

{
  "query": "query BrochureById($id: Int!) { brochure(id: $id) { id name slug pageMessage description popularity categories { id name slug } attachments { id filename url } seoMetadata } }",
  "variables": { "id": 1 }
}

{
  "query": "query BrochureBySlug($slug: String!) { brochure(slug: $slug) { id name slug pageMessage description popularity categories { id name slug } attachments { id filename url } } }",
  "variables": { "slug": "replace-me" }
}

{
  "query": "query Brochures($search: String, $categoryId: Int, $pageSize: Int, $currentPage: Int) { brochures(search: $search, categoryId: $categoryId, pageSize: $pageSize, currentPage: $currentPage) { totalCount brochures { id name slug } } }",
  "variables": { "search": "", "categoryId": null, "pageSize": 20, "currentPage": 1 }
}

{
  "query": "query BrochureCategoryById($id: Int!) { brochureCategory(id: $id) { id name slug pageMessage parent { id name } childs { id name } brochures { id name slug } } }",
  "variables": { "id": 1 }
}

{
  "query": "query BrochureCategoryBySlug($slug: String!) { brochureCategory(slug: $slug) { id name slug parent { id name } childs { id name } brochures { id name } } }",
  "variables": { "slug": "replace-me" }
}

{
  "query": "query BrochureCategories($rootsOnly: Boolean, $parentId: Int) { brochureCategories(rootsOnly: $rootsOnly, parentId: $parentId) { id name slug childs { id name } } }",
  "variables": { "rootsOnly": true, "parentId": null }
}

{
  "query": "query ProductById($id: Int!) { product(id: $id) { id name defaultCode slug price qty isDangerousGoods make { id name code } dataSource { id code name } weightGr lengthMm widthMm heightMm applications { id model serie vehicleTypeCode make { id name } brochureId brochureName brochureSlug } tvhNumber tvhPrice tvhListPrice tvhQuantityInStock qualityBrand stockUnitMatrixDesc unitCode { id code description } availabilityCode { id code description } isReconditioned isNonReturnable isNonCancellable surchargeAmount environmentalFee minimumOrderQuantity orderable notOrderableReason tvhQuantityDiscounts { id qty price } replacedBy { id name } latestProduct { id name } } }",
  "variables": { "id": 1 }
}

{
  "query": "query ProductBySlug($slug: String!) { product(slug: $slug) { id name defaultCode slug price make { id name code } applications { id model serie } } }",
  "variables": { "slug": "replace-me" }
}

{
  "query": "query Products($filter: ProductFilterInput, $currentPage: Int, $pageSize: Int, $sort: ProductSortInput) { products(filter: $filter, currentPage: $currentPage, pageSize: $pageSize, sort: $sort) { ... on ProductList { totalCount minPrice maxPrice products { id name defaultCode price make { id name } } facets { makes { id name code count } families { id name count } subfamilies { id name parentId count } subsubfamilies { id name parentId count } } } } }",
  "variables": { "filter": { "facets": { "makeIds": [], "familyIds": [], "subfamilyIds": [], "subsubfamilyIds": [] } }, "currentPage": 1, "pageSize": 20, "sort": {} }
}

{
  "query": "query ProductsSearch($search: String, $pageSize: Int, $currentPage: Int) { products(search: $search, pageSize: $pageSize, currentPage: $currentPage) { ... on ProductList { totalCount products { id name defaultCode price make { name } } } } }",
  "variables": { "search": "shim", "pageSize": 20, "currentPage": 1 }
}

{
  "query": "mutation CartAddItem($productId: Int!, $quantity: Int!) { cartAddItem(productId: $productId, quantity: $quantity) { ... on CartData { order { id orderLines { id quantity product { id name defaultCode } } } } } }",
  "variables": { "productId": 1, "quantity": 1 }
}

{
  "query": "mutation CartUpdateItem($lineId: Int!, $quantity: Int!) { cartUpdateItem(lineId: $lineId, quantity: $quantity) { ... on CartData { order { id orderLines { id quantity } } } } }",
  "variables": { "lineId": 1, "quantity": 2 }
}

{
  "query": "mutation CartRemoveItem($lineId: Int!) { cartRemoveItem(lineId: $lineId) { ... on CartData { order { id orderLines { id } } } } }",
  "variables": { "lineId": 1 }
}

{
  "query": "mutation CartClear { cartClear { id orderLines { id } brochureLines { id } } }",
  "variables": {}
}

{
  "query": "mutation CartAddBrochureItem($brochureId: Int!, $machineSerial: String, $partNumber: String, $commentary: String) { cartAddBrochureItem(brochureId: $brochureId, machineSerial: $machineSerial, partNumber: $partNumber, commentary: $commentary) { ... on CartData { order { id brochureLines { id brochureId brochureName machineSerial partNumber commentary } } } } }",
  "variables": { "brochureId": 1, "machineSerial": "MLT 1035", "partNumber": "ABC-123", "commentary": "please ship as soon as possible" }
}

{
  "query": "mutation CartRemoveBrochureItem($lineId: Int!) { cartRemoveBrochureItem(lineId: $lineId) { ... on CartData { order { id brochureLines { id } } } } }",
  "variables": { "lineId": 1 }
}

{
  "query": "mutation ConfirmOrder($name: String, $email: String, $phone: String, $comment: String) { confirmOrder(name: $name, email: $email, phone: $phone, comment: $comment) { done } }",
  "variables": { "name": "Test Customer", "email": "test@example.com", "phone": "+1 555 0100", "comment": "" }
}
